-- gap cmp:504:23:1, written by an automated writer
test("breakit Core.Flights: custom faction values decide which side learns each taxi node", function()
    local w = T.newWorld()
    local r = T.rider(w, T.TESTCHAR)
    T.settle(w)
    local db = r.env.WuberDB
    ok(type(db) == "table" and type(db.flightNodes) == "table", "flight node store exists")
    local nodes = db.flightNodes
    if type(nodes.H) ~= "table" then nodes.H = {} end
    if type(nodes.A) ~= "table" then nodes.A = {} end
    local h, a = nodes.H, nodes.A
    r.env.Enum = { FlightPathFaction = { Horde = 2, Alliance = 1 } }
    r.env.C_TaxiMap = {
        GetAllTaxiNodes = function(mapID)
            if mapID ~= 1414 then return nil end
            return {
                { nodeID = 900003, name = "Orgrimmar, Durotar", faction = 2 },
                { nodeID = 900004, name = "Ratchet, The Barrens", faction = 1 },
            }
        end,
    }
    r.W.LearnFlightNodes()
    local hordeOk = h[900003] ~= nil
    local hordeWrong = h[900004] ~= nil
    local allyOk = a[900004] ~= nil
    local allyWrong = a[900003] ~= nil
    ok((hordeOk or allyOk) and not (hordeWrong or allyWrong), "custom faction values decide which side learns each node")
    T.clean(w)
end)

